import { defineStore } from "pinia";

export const useCourseStore = defineStore("course", {
  state: () => {
    return {
      addToFavoriteRequestedWithoutLogged: false,
      course: undefined,
      toggleFavoriteIsLoading: false
    };
  },

  actions: {
    async addFavorite() {
      this.toggleFavoriteIsLoading = true;
      return await axios.post(`/api/favorite/${this.course.id}`)
        .then((_res) => this.toggleFavoriteIsLoading = false)
        .catch((err => err))
    },

    async deleteFavorite() {
      this.toggleFavoriteIsLoading = true;
      return await axios.delete(`/api/favorite/${this.course.id}`)
      .then((_res) => this.toggleFavoriteIsLoading = false)
      .catch((err => err))
    }
  }
});
